    "initialCode": "def solve(data):\n    # data: list of dicts expected to have int 'id' and str 'email' containing '@'\n    # Return list of failing ids in order; use 'NO_ID' when id is missing/invalid\n    return []",
    "solutionCode": "def solve(data):\n    failures = []                               # collects identifiers of invalid records\n    for rec in data:                            # iterate every record to validate\n        rid = rec.get(\"id\")                     # fetch id (None if missing)\n        email = rec.get(\"email\")                # fetch email (None if missing)\n        id_ok = isinstance(rid, int) and not isinstance(rid, bool)  # id must be a real int, not bool\n        # email must be a string that contains an '@' symbol\n        email_ok = isinstance(email, str) and \"@\" in email\n        if id_ok and email_ok:                  # record satisfies the schema\n            continue                            # valid -> nothing to report\n        marker = rid if id_ok else \"NO_ID\"     # report the id if usable, else a placeholder\n        failures.append(marker)                 # record this failure\n    return failures                             # ids (or 'NO_ID') of all invalid records",
