      {
        "input": "[]",
        "expected": "[]"
      },
      {
        "input": "['10,Eve,40','11,Sam,22','12,Lia,35']",
        "expected": "[{'id': 10, 'name': 'Eve', 'age': 40}, {'id': 11, 'name': 'Sam', 'age': 22}, {'id': 12, 'name': 'Lia', 'age': 35}]"
      }
