    "initialCode": "def solve(data):\n    # data = [facts, dims]; facts: [{'event_id','country_code'}], dims: [{'country_code','country_name'}]\n    # Left broadcast join on country_code; missing -> 'UNKNOWN'. Preserve fact order.\n    return []",
    "solutionCode": "def solve(data):\n    # PySpark equivalent:\n    #   facts = spark.createDataFrame(data[0]); dims = spark.createDataFrame(data[1])\n    #   j = facts.join(F.broadcast(dims), on=\"country_code\", how=\"left\")           # broadcast left join\n    #   out = j.select(\"event_id\", F.coalesce(\"country_name\", F.lit(\"UNKNOWN\")).alias(\"country_name\"))\n    #   return [r.asDict() for r in out.collect()]\n    facts, dims = data[0], data[1]                     # large probe side, small broadcast side\n    lookup = {d[\"country_code\"]: d[\"country_name\"] for d in dims}  # broadcast hash map sent to every executor\n    result = []                                        # collect buffer\n    for f in facts:                                    # stream the large side, no shuffle of facts\n        name = lookup.get(f[\"country_code\"], \"UNKNOWN\")  # local lookup; coalesce missing to UNKNOWN (left join)\n        result.append({\"event_id\": f[\"event_id\"], \"country_name\": name})  # emit enriched row\n    return result                                      # collect() to driver",
