    "initialCode": "def solve(data):\n    # data: list of {'category': str, 'product': str, 'revenue': int}\n    # Top 2 per category by revenue desc, tie-break product asc. Return rows with 'rank'.\n    return []",
    "solutionCode": "def solve(data):\n    # Spark SQL equivalent:\n    #   df.createOrReplaceTempView(\"p\")\n    #   spark.sql('''SELECT category, product, revenue, rank FROM (\n    #     SELECT *, ROW_NUMBER() OVER (PARTITION BY category ORDER BY revenue DESC, product ASC) AS rank\n    #     FROM p) WHERE rank <= 2 ORDER BY category, rank''')\n    by_cat = {}                                   # group rows by category (PARTITION BY category)\n    for r in data:                                # scan all rows once\n        by_cat.setdefault(r[\"category\"], []).append(r)  # collect into per-category buckets\n    out = []                                       # final result rows\n    for cat in sorted(by_cat):                     # deterministic category order (ORDER BY category)\n        ranked = sorted(by_cat[cat], key=lambda r: (-r[\"revenue\"], r[\"product\"]))  # ORDER BY revenue DESC, product ASC\n        for i, r in enumerate(ranked[:2], start=1):  # ROW_NUMBER then WHERE rank <= 2\n            out.append({\"category\": cat, \"product\": r[\"product\"], \"revenue\": r[\"revenue\"], \"rank\": i})  # emit top-N\n    return out                                     # already (category, rank) ordered",
