      {
        "input": "[]",
        "expected": "[]"
      },
      {
        "input": "[{'product':'X','month':'Mar','sales':3},{'product':'X','month':'Mar','sales':4}]",
        "expected": "[{'product': 'X', 'Mar': 7}]"
      }
