    "exampleInput": "[{'op':'I','id':1,'value':10},{'op':'U','id':1,'value':15},{'op':'I','id':2,'value':20},{'op':'D','id':2,'value':0}]",
    "exampleOutput": "[{'id': 1, 'value': 15}]",
